import{_ as a,H as s,f as t,i as n}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"09｜工程初始化（下）：前端工程与一键启动","description":"","frontmatter":{},"headers":[{"level":2,"title":"前端 Vue 工程搭建","slug":"前端-vue-工程搭建","link":"#前端-vue-工程搭建","children":[{"level":3,"title":"第一步：项目骨架","slug":"第一步-项目骨架","link":"#第一步-项目骨架","children":[]},{"level":3,"title":"第二步：axios 统一请求层","slug":"第二步-axios-统一请求层","link":"#第二步-axios-统一请求层","children":[]},{"level":3,"title":"第三步：路由和页面空壳","slug":"第三步-路由和页面空壳","link":"#第三步-路由和页面空壳","children":[]}]},{"level":2,"title":"前后端联通","slug":"前后端联通","link":"#前后端联通","children":[]},{"level":2,"title":"启动脚本","slug":"启动脚本","link":"#启动脚本","children":[]},{"level":2,"title":"验收时刻","slug":"验收时刻","link":"#验收时刻","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/09｜工程初始化（下）：前端工程与一键启动.md","filePath":"ClaudeCode企业级全链路开发实战/09｜工程初始化（下）：前端工程与一键启动.md","lastUpdated":1779815375000}'),i={name:"ClaudeCode企业级全链路开发实战/09｜工程初始化（下）：前端工程与一键启动.md"};function p(l,e,o,r,c,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_09-工程初始化-下-前端工程与一键启动" tabindex="-1">09｜工程初始化（下）：前端工程与一键启动 <a class="header-anchor" href="#_09-工程初始化-下-前端工程与一键启动" aria-label="Permalink to &quot;09｜工程初始化（下）：前端工程与一键启动&quot;">​</a></h1><p>你好，我是Robert。</p><p>上一讲我们搭好了后端骨架——Maven多模块结构、公共基础设施、健康检查接口， <code>java -jar</code> 能跑，访问 <code>/api/v1/health</code> 返回200。</p><p>这一讲把剩下的补齐：前端Vue工程、前后端联通、启动脚本。做完之后，你执行一个 <code>./start.sh</code>，后端前端同时起来，浏览器打开就能看到Hify的页面。</p><p>从零到能跑的完整闭环，这一讲交付完成。</p><h2 id="前端-vue-工程搭建" tabindex="-1">前端 Vue 工程搭建 <a class="header-anchor" href="#前端-vue-工程搭建" aria-label="Permalink to &quot;前端 Vue 工程搭建&quot;">​</a></h2><p>和上一讲后端一样，前端初始化也要分步做。我分成三步：项目骨架、axios统一请求层、路由和页面空壳。上一讲建立的任务拆解方法论直接复用，不再解释为什么要拆——按依赖关系排序，每步验证后进入下一步。</p><h3 id="第一步-项目骨架" tabindex="-1">第一步：项目骨架 <a class="header-anchor" href="#第一步-项目骨架" aria-label="Permalink to &quot;第一步：项目骨架&quot;">​</a></h3><p>给Claude Code的指令思路：</p><blockquote><p>初始化Hify前端项目hify-web。Vue 3 + TypeScript + Vite + Element Plus。目录结构按CLAUDE.md中定义的前端结构来。Vite开发服务器配置代理：/api请求转发到localhost:8080。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/42df25ffef87fa9e041f811c7ef50388.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/42df25ffef87fa9e041f811c7ef50388.png" alt=""></a></p><p>这一步比较标准化，Claude Code一般不会出大问题。拿到输出后检查两件事：目录结构和CLAUDE.md里定义的是否一致；Vite代理配置是否正确，开发阶段前端跑在5173端口，通过Vite代理转发 <code>/api</code> 请求到后端8080端口，解决跨域问题。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/e0f80023f9927337bfc524542820cb3f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/e0f80023f9927337bfc524542820cb3f.png" alt=""></a></p><p>是不是很快。说实话，我一点不懂前端。但是通过上面的指令就有一个前端服务了。这里需要注意的是： <strong>提示词要完整且清晰</strong>。你可以参考一下上面的提示词。</p><h3 id="第二步-axios-统一请求层" tabindex="-1">第二步：axios 统一请求层 <a class="header-anchor" href="#第二步-axios-统一请求层" aria-label="Permalink to &quot;第二步：axios 统一请求层&quot;">​</a></h3><p>这一步值得多讲一下，因为它是前端和后端规范体系的接合点。</p><p>后端定了统一响应格式 <code>Result&amp;lt;T&gt;</code>，每个接口都返回 <code>{ code: 200, message: &quot;success&quot;, data: {...} }</code>。前端的axios封装要和这套格式对接，让业务代码不需要每次都手动处理code判断和data解包。</p><p>给Claude Code的指令思路：</p><blockquote><p>在hify-web/src/utils/下创建request.ts，封装axios实例。baseURL设为/api。响应拦截器里判断code：200直接返回data 字段（自动解包），非200用Element Plus的ElMessage.error提示message，然后reject。导出get、post、put、del四个方法。</p></blockquote><p>为什么要在拦截器里自动解包data？因为如果不这么做，后面每个页面调接口都要写：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> providerApi.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> result.data  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 每次都要 .data</span></span></code></pre></div><p>封装之后直接就是：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> providerApi.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 直接拿到 data</span></span></code></pre></div><p>看起来是个小事，但几十个接口累积下来，代码干净很多。来看生成的request.ts的代码：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import axios from &#39;axios&#39;</span></span>
<span class="line"><span>import { ElMessage } from &#39;element-plus&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const instance = axios.create({</span></span>
<span class="line"><span>  baseURL: &#39;/api&#39;,</span></span>
<span class="line"><span>  timeout: 60000,</span></span>
<span class="line"><span>})</span></span>
<span class="line"><span></span></span>
<span class="line"><span>instance.interceptors.response.use(</span></span>
<span class="line"><span>  (response) =&amp;gt; {</span></span>
<span class="line"><span>    const { code, message, data } = response.data</span></span>
<span class="line"><span>    if (code !== 200) {</span></span>
<span class="line"><span>      ElMessage.error(message || &#39;请求失败&#39;)</span></span>
<span class="line"><span>      return Promise.reject(new Error(message))</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return data</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  (error) =&amp;gt; {</span></span>
<span class="line"><span>    ElMessage.error(error.message || &#39;网络异常&#39;)</span></span>
<span class="line"><span>    return Promise.reject(error)</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const get = &amp;lt;T&amp;gt;(url: string, params?: object): Promise&amp;lt;T&amp;gt; =&amp;gt;</span></span>
<span class="line"><span>  instance.get(url, { params })</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const post = &amp;lt;T&amp;gt;(url: string, data?: object): Promise&amp;lt;T&amp;gt; =&amp;gt;</span></span>
<span class="line"><span>  instance.post(url, data)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const put = &amp;lt;T&amp;gt;(url: string, data?: object): Promise&amp;lt;T&amp;gt; =&amp;gt;</span></span>
<span class="line"><span>  instance.put(url, data)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const del = &amp;lt;T&amp;gt;(url: string): Promise&amp;lt;T&amp;gt; =&amp;gt;</span></span>
<span class="line"><span>  instance.delete(url)</span></span></code></pre></div><p>然后让Claude Code基于这个封装写一个示例API文件：</p><blockquote><p>在hify-web/src/api/下创建health.ts，用封装好的request调用GET /api/v1/health。导出getHealth方法。</p></blockquote><p>文件代码是：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import { get } from &#39;&amp;#64;/utils/request&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export const getHealth = () =&amp;gt; get&amp;lt;string&amp;gt;(&#39;/v1/health&#39;)</span></span></code></pre></div><p>这个文件只有几行代码，但它验证了整条链路——axios封装、代理配置、接口路径规范——是否都通。</p><p>回过头看，这就是为什么06讲要把接口规范写进CLAUDE.md，因为不只后端在用，前端axios封装也在对着同一份规范做。后端的 <code>Result&amp;lt;T&gt;</code> 格式、接口路径规则、错误码定义，前端全部照着来。一份规范，两端对齐。</p><h3 id="第三步-路由和页面空壳" tabindex="-1">第三步：路由和页面空壳 <a class="header-anchor" href="#第三步-路由和页面空壳" aria-label="Permalink to &quot;第三步：路由和页面空壳&quot;">​</a></h3><p>给Claude Code的指令是：</p><blockquote><p>在hify-web中配置Vue Router，创建以下路由和对应的空壳页面组件：模型管理、Agent管理、对话。每个空壳页面只显示页面名称，比如ProviderList.vue里就一行&quot;模型提供商管理&quot;。再创建一个App.vue布局：左侧Element Plus菜单栏（三个菜单项对应三个路由），右侧内容区用router-view。</p></blockquote><p>这一步生成的是一个有完整导航结构的空壳应用——左边菜单、右边内容，点菜单能切换页面，每个页面都是占位文字。后面往里填内容就行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/608730ab62b366b6fed1ca2574769f89.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/608730ab62b366b6fed1ca2574769f89.png" alt=""></a></p><h2 id="前后端联通" tabindex="-1">前后端联通 <a class="header-anchor" href="#前后端联通" aria-label="Permalink to &quot;前后端联通&quot;">​</a></h2><p>前端搭好了，后端上一讲已经能跑了。现在把它们连起来。</p><p>这一步验证的是完整链路：Vite代理配置对不对、axios封装能不能用、前后端的接口格式能不能对上。</p><p>把前端的ProviderList.vue改一下，让它调用健康检查接口并显示结果：</p><blockquote><p>修改ProviderList.vue，在页面加载时调用getHealth()，把返回结果显示在页面上。如果调用成功显示绿色的&quot;后端已连接：Hify is running&quot;，失败显示红色的&quot;后端未连接&quot;。</p></blockquote><p>启动后端、启动前端，打开浏览器 <code>http://localhost:5173</code>，你应该能看到左侧菜单、右侧显示绿色的“后端已连接”。但是，却是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/c65e02831231314037638f27acf432e5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/c65e02831231314037638f27acf432e5.png" alt=""></a></p><p>看了一眼，发现hify server被我关了，启动后：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/ee181acea49feb3b82201aa2yyd3197a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/ee181acea49feb3b82201aa2yyd3197a.png" alt=""></a></p><p>看到了，说明前后端联通成功——axios封装正常、Vite代理正常、后端接口正常、Result格式前端能正确解析。如果显示红色，就把浏览器控制台的错误信息贴给Claude Code让它排查。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/c4cebd3e995b5936137641c30574da7a.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/c4cebd3e995b5936137641c30574da7a.jpg" alt=""></a></p><h2 id="启动脚本" tabindex="-1">启动脚本 <a class="header-anchor" href="#启动脚本" aria-label="Permalink to &quot;启动脚本&quot;">​</a></h2><p>到这一步，前后端都能跑了，但每次启动要开两个终端、输两条命令。写个脚本让它一键搞定。</p><p>还记得01讲的三层分工吗？启动脚本、Makefile这些就是典型的第三层——AI全权处理，你验收结果就行。脚本逻辑不复杂，但手写容易漏细节（进程管理、日志输出、端口检查），交给Claude Code特别合适。不需要逐行review shell语法，跑一下 <code>start.sh</code> 能起来就过了。</p><p><strong>start.sh</strong></p><blockquote><p>写一个start.sh脚本，放在项目根目录。功能：检查MySQL和Redis是否可用，构建后端并后台启动，轮询等待后端健康检查通过，启动前端开发服务器。加上错误处理：任何一步失败就停止并提示。</p></blockquote><p><strong>stop.sh</strong></p><blockquote><p>写一个stop.sh脚本，优雅停止后端和前端进程。按PID文件找进程，先SIGTERM再等待，超时SIGKILL。</p></blockquote><p><strong>Makefile</strong></p><blockquote><p>写一个Makefile，包含以下target：make start（启动）、make stop（停止）、make restart（重启）、make build（构建后端 + 前端）、make clean（清理构建产物）、make package（打包成可分发的 tar.gz）。</p></blockquote><p>这里不展示输入和输出的细节了，实操课中会演示，直接展示结果。</p><p>这 3 个文件加起来可能就一两百行脚本，但它们让整个项目的使用体验提升了一个档次。拉下代码， <code>make start</code> 就跑起来了， <code>make package</code> 就能打包分发。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/d5ecdeff389f1c6a7bdf12e6374b1715.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/d5ecdeff389f1c6a7bdf12e6374b1715.png" alt=""></a></p><h2 id="验收时刻" tabindex="-1">验收时刻 <a class="header-anchor" href="#验收时刻" aria-label="Permalink to &quot;验收时刻&quot;">​</a></h2><p>所有东西都就绪了。最终验收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.sh</span></span></code></pre></div><p>你应该看到这样的输出：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-e [INFO]  检查 MySQL localhost:3306 ...</span></span>
<span class="line"><span>-e [ERROR] MySQL 不可达（localhost:3306），请先启动 MySQL</span></span></code></pre></div><p>这里是因为MySQL没配置。调整配置后，打开浏览器访问 <code>http://localhost:5173</code>：</p><ul><li>左侧看到三个菜单：模型管理、Agent管理、对话</li><li>点“模型管理”，右侧显示绿色的“后端已连接：Hify is running”</li><li>点其他菜单，显示对应的占位文字</li></ul><p>看到这些，工程初始化就完成了。你手上有了一个前后端都能跑的空项目，结构清晰、规范就绪、一键启动。后面的工作就是往这个骨架里填功能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/ee181acea49feb3b82201aa2yyd3197a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966045/ee181acea49feb3b82201aa2yyd3197a.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>我们用两节课完成了Hify的工程初始化——后端能跑、前端能开、一键启动、前后端联通。最终，你手上有了一个完整的“空项目。</p><p>最后我们回顾一下这两讲的方法论：</p><p><strong>任务拆解。</strong> 工程初始化体量大，不能一条指令搞定。按依赖关系拆成有序的步骤，每步验证后再进入下一步。判断标准：生成量超出一次review范围、步骤间有依赖，满足其一就拆。</p><p><strong>基础设施先行。</strong> 先搭Maven骨架、再搭公共模块、再搭业务空壳、再搭前端、最后写脚本。顺序不能乱，因为后面的每一步都依赖前面的结果。</p><p><strong>每步验收。</strong> 不是搭完全部才验收，而是每一步做完就验证。每一个验收点给你信心：到这里是对的。</p><p>不过，工程初始化完成不代表可以直接写业务了。现在的空项目还缺一层东西——基础组件。数据库怎么做分页、接口入参怎么校验、调外部API的客户端怎么封装、线程池怎么配、熔断怎么搞，这些是所有业务模块都会用到的底层能力。</p><p>不过下一讲我们要换一种协作模式，不是你告诉Claude Code做什么，而是先让它告诉你该做什么。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这两讲工程初始化的过程中，Claude Code做了大量“模板性”的工作，包括项目结构、配置文件、公共组件、脚本。回想一下你自己平时做项目，有哪些类似的不难但繁琐的工作？列出3个你觉得最适合交给AI做的，以及你会怎么给它描述需求。</p><p>期待你的分享。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,80)])])}const g=a(i,[["render",p]]);export{E as __pageData,g as default};
